SELECT ROUND(o,0), ROUND(n,0), ROUND(c,0), ROUND(o+n-c,0) FROM (SELECT (SELECT SUM(closing_balance) FROM loan_monthly_snapshot WHERE snapshot_date=DATE '2021-11-30' AND loan_status<>'Closed') AS o, (SELECT SUM(original_amount) FROM loan WHERE origination_date>=DATE '2021-12-01' AND origination_date<=DATE '2021-12-31') AS n, (SELECT SUM(closing_balance) FROM loan_monthly_snapshot WHERE snapshot_date=DATE '2021-12-31' AND loan_status<>'Closed') AS c)
